{
  "decisions": [
    {
      "requirement_id": "MED-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by executing the application to create a record and observing that all specified fields are captured."
    },
    {
      "requirement_id": "MED-002",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The distinct colours for the four triage categories are verified by running the application and visually observing the UI elements."
    },
    {
      "requirement_id": "MED-003",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by inputting vital signs within and outside the defined ranges and observing the acceptance or rejection behavior."
    },
    {
      "requirement_id": "MED-004",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by disconnecting the network, creating 500 records, and confirming the application remains functional and data is stored locally."
    },
    {
      "requirement_id": "MED-005",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by simulating conflicting edits, restoring connectivity, and observing the synchronization and conflict resolution behavior."
    },
    {
      "requirement_id": "MED-006",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The requirement is verified by inspecting the code or configuration to confirm that AES-256 encryption is applied to the local storage."
    },
    {
      "requirement_id": "MED-007",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The requirement is verified by a user wearing surgical gloves operating the application to demonstrate that all functions are accessible."
    },
    {
      "requirement_id": "MED-008",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by running the application under the defined usage profile and measuring the battery life to ensure it exceeds 8 hours."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies a behavioral response (HTTP 401) to a specific input condition (missing token), which is verified by executing the system with test requests."
    },
    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Role-based access control and the resulting HTTP 403 response are functional behaviors that must be observed by sending requests with different role credentials."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "Rate limiting behavior, including the HTTP 429 status and Retry-After header, is verified by sending a controlled volume of requests to exceed the threshold and observing the response."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Analiz"
      ],
      "rationale": "Verifying a 99th percentile latency metric under a specific load requires statistical analysis of performance data collected during load testing."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "The timeout behavior and HTTP 504 response are functional outcomes that can be observed by simulating a slow backend service and checking the gateway's reaction."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "The ability to apply configuration changes without restart or request loss is a dynamic behavior that must be demonstrated by modifying settings while traffic is active and observing system stability."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "The generation of structured logs with specific fields is verified by sending requests and inspecting the resulting log entries for the required data points."
    },
    {
      "requirement_id": "SW-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Monthly availability is a statistical metric derived from uptime and downtime records over a period, requiring analysis of operational data rather than a single functional test."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "AI-001",
      "methods": [
        "Test"
      ],
      "rationale": "The behavior of classifying documents into one of 12 categories and returning a confidence score between 0 and 1 is verified by executing the service with sample inputs and observing the output."
    },
    {
      "requirement_id": "AI-002",
      "methods": [
        "Analiz"
      ],
      "rationale": "Achieving a specific macro-averaged F1 score on a held-out evaluation set requires statistical analysis and model evaluation rather than simple functional testing."
    },
    {
      "requirement_id": "AI-003",
      "methods": [
        "Test"
      ],
      "rationale": "The routing logic for low-confidence documents is verified by submitting documents with confidence scores below 0.60 and observing that they are directed to the human review queue."
    },
    {
      "requirement_id": "AI-004",
      "methods": [
        "Test"
      ],
      "rationale": "Performance under load is verified by executing a load test at 50 requests per second and measuring the response times to ensure the 95th percentile is within 500 ms."
    },
    {
      "requirement_id": "AI-005",
      "methods": [
        "Test"
      ],
      "rationale": "The logging functionality is verified by sending requests and checking the system logs or database to confirm that the model version, input hash, and predicted category are recorded."
    },
    {
      "requirement_id": "AI-006",
      "methods": [
        "Analiz"
      ],
      "rationale": "Detecting deviation in the weekly distribution of predicted categories using a population stability index requires statistical analysis of the data over time."
    },
    {
      "requirement_id": "AI-007",
      "methods": [
        "Test"
      ],
      "rationale": "The provision of the three most contributing text passages is verified by executing a classification request and inspecting the response payload for the required passages."
    },
    {
      "requirement_id": "AI-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Comparing recall metrics between Turkish and English documents to ensure the difference is within 5 percentage points requires statistical analysis of the model's performance on separate language subsets."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KK-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gecikme süresi, sistemin çalıştırılması ve sensör girdilerinin verilmesiyle ölçülerek doğrulanabilir."
    },
    {
      "requirement_id": "KK-002",
      "methods": [
        "Test"
      ],
      "rationale": "Yük testi ile 2.000 iz altında ekran yenileme hızının 10 Hz'in üzerinde kalıp kalmadığı gözlemlenebilir."
    },
    {
      "requirement_id": "KK-003",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Operatörün seçtiği izin detaylarını ekranda görüntülemesi, sistemin çalıştırılıp gözlemlenmesiyle gösterilebilir."
    },
    {
      "requirement_id": "KK-004",
      "methods": [
        "Test"
      ],
      "rationale": "Güncelleme akışının durdurulmasıyla 30 ve 120 saniye sonrası iz durumunun değişimi test edilerek doğrulanabilir."
    },
    {
      "requirement_id": "KK-005",
      "methods": [
        "Test"
      ],
      "rationale": "Tanımlı bölgeye iz girdiğinde görsel ve sesli uyarıların tetiklenip tetiklenmediği sistemin çalıştırılmasıyla test edilebilir."
    },
    {
      "requirement_id": "KK-006",
      "methods": [
        "Test"
      ],
      "rationale": "Mesaj gönderimi sonrası iletim süresi ve durum bildirimi, sistemin çalıştırılması ve girdi verilmesiyle ölçülebilir."
    },
    {
      "requirement_id": "KK-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Kayıt defterinin (log) zaman damgası, kullanıcı kimliği ve değiştirilemezlik özellikleri, log dosyalarının ve yapılandırmanın gözle denetlenmesiyle doğrulanabilir."
    },
    {
      "requirement_id": "KK-008",
      "methods": [
        "Test"
      ],
      "rationale": "Birincil sunucunun arızalandırılmasıyla yedek sunucunun devralma süresi ve veri bütünlüğü, sistemin çalıştırılmasıyla test edilebilir."
    }
  ]
}

