{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": [
        "Test"
      ],
      "rationale": "Sistemin e-Devlet entegrasyonu ile oturum açma işlevinin çalışıp çalışmadığı, gerçek veya simüle edilmiş kimlik doğrulama girdileriyle sistemin çalıştırılarak gözlemlenmesiyle doğrulanabilir."
    },
    {
      "requirement_id": "KMU-002",
      "methods": [
        "Test"
      ],
      "rationale": "Oturumun 15 dakika hareketsizlik sonrası sonlandırılması ve yönlendirme davranışı, zamanlayıcı mekanizmasının çalıştırılarak ve beklenen yönlendirmenin gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "KMU-003",
      "methods": [
        "Test"
      ],
      "rationale": "Art arda 5 başarısız giriş denemesi sonrası hesap kilitlenmesi ve 30 dakikalık süre, sisteme kasıtlı olarak hatalı girdiler verilerek ve kilit durumunun gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "KMU-004",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya yükleme sınırlarının (biçim, boyut, adet) uygulanıp uygulanmadığı, farklı senaryolarda dosya yüklenerek sistemin kabul veya reddetme davranışının gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "KMU-005",
      "methods": [
        "Test"
      ],
      "rationale": "Benzersiz takip numarası üretimi ve e-posta bildirimi işlevi, bir başvuru tamamlanarak numaranın üretilip üretilmediğinin ve e-postanın gönderilip gönderilmediğinin gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "KMU-006",
      "methods": [
        "Test"
      ],
      "rationale": "Taslak saklama ve 30 gün içinde devam etme işlevi, bir başvuru yarım bırakılarak ve daha sonra (zaman simülasyonu veya gerçek bekleme ile) sisteme girilip taslağın geri yüklenip yüklenmediğinin gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "KMU-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "WCAG 2.1 AA uyumluluğu, kullanıcı arayüzü kodunun, HTML yapısının ve erişilebilirlik araçlarının çıktısının standartlara göre gözle denetlenerek (inceleme) doğrulanır."
    },
    {
      "requirement_id": "KMU-008",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Verilerin yalnızca Türkiye sınırları içindeki sunucularda saklanması, altyapı yapılandırma dosyalarının, sunucu konum bilgileri ve veri akış şemalarının gözle denetlenerek (inceleme) doğrulanır."
    }
  ]
}

