{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "Verification of AES-256 encryption for stored casualty data",
      "covers": [
        "MED-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The tablet is running the Field Triage Tablet Application. At least one casualty record has been created and saved to the local storage.",
      "test_inputs": "A valid casualty record (e.g., Patient ID: PT-123, Name: John Doe, Condition: Minor).",
      "assumptions": "Access to the underlying file system or storage media is available for inspection. A tool capable of analyzing file headers or metadata for encryption signatures is available.",
      "steps": [
        {
          "no": 1,
          "action": "Create a new casualty record with unique identifiable data (e.g., 'TEST_PATIENT_XYZ') and save it through the application interface.",
          "expected": "The application confirms the record has been saved successfully."
        },
        {
          "no": 2,
          "action": "Locate the physical storage file or database segment corresponding to the newly saved record on the tablet's file system.",
          "expected": "The file is accessible via the file system explorer or command line."
        },
        {
          "no": 3,
          "action": "Inspect the binary content or metadata of the storage file to verify the encryption method.",
          "expected": "The data is not stored in plaintext. The storage format or metadata indicates that AES-256 encryption is applied (e.g., specific file extension, header magic bytes, or encryption metadata field)."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "Battery life verification under defined usage profile",
      "covers": [
        "MED-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The tablet is fully charged (100%). The 'defined usage profile' is documented (e.g., continuous screen-on, typical triage data entry, GPS active, Wi-Fi/Cellular active). The tablet is connected to a power meter or the battery percentage display is visible.",
      "test_inputs": "Usage profile definition: Continuous operation with screen brightness at 50%, typical data entry frequency (1 entry per minute), and active network connection.",
      "assumptions": "The 'defined usage profile' is standardized and documented in the project specifications. The tablet's battery health is within normal operating parameters.",
      "steps": [
        {
          "no": 1,
          "action": "Start the Field Triage Tablet Application and initiate the defined usage profile (e.g., begin continuous data entry and keep the screen on).",
          "expected": "The application is running and the tablet battery indicator shows 100% (or near 100%). The start time is recorded."
        },
        {
          "no": 2,
          "action": "Operate the tablet continuously according to the defined usage profile for 8 hours.",
          "expected": "The tablet remains powered on and responsive throughout the 8-hour period. The application remains operational."
        },
        {
          "no": 3,
          "action": "Check the battery status after the 8-hour operation period.",
          "expected": "The tablet has not shut down due to battery depletion. The battery level is greater than 0%."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-KK-005-01",
      "title": "Tanımlı bölgeye giren iz için görsel ve sesli uyarı verilmesi",
      "covers": [
        "KK-005"
      ],
      "type": "Normal",
      "priority": "Yüksek",
