      "title": "Operatörler arası metin mesajının 2 saniye içinde iletilmesi ve durumunun gösterilmesi",
      "covers": [
        "KK-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "İki operatör istasyonu (Gönderen ve Alıcı) sisteme bağlı ve çevrim içidir.",
      "test_inputs": "Kısa bir metin mesajı (ör: 'Test Mesajı 1').",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Gönderen operatör, Alıcı operatöre 'Test Mesajı 1' metnini gönderir ve gönderim zamanı kaydedilir.",
          "expected": "Gönderen arayüzünde mesajın iletildiğine dair durum göstergesi (ör: 'İletildi' veya onay ikonu) belirir."
