          "action": "Alıcı operatörün ekranında mesajın görünmesi beklenir.",
          "expected": "Mesaj, gönderimden itibaren en geç 2 saniye içinde Alıcı operatörün ekranında görünür."
        },
        {
          "no": 3,
          "action": "Mesajın içeriği kontrol edilir.",
          "expected": "Alıcıdaki mesaj içeriği, gönderilene birebir eşittir ('Test Mesajı 1')."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Offline operation and local storage capacity",
      "covers": [
        "MED-004"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is installed and configured on the tablet. Network connectivity is disabled (Airplane mode or no signal). The local database is empty.",
      "test_inputs": "500 distinct casualty records with valid data.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Create 500 casualty records sequentially in the application while offline.",
          "expected": "All 500 records are successfully created and saved without errors."
        },
        {
          "no": 2,
          "action": "Attempt to create a 501st casualty record.",
          "expected": "The record is successfully created (as the requirement states 'at least 500', implying capacity >= 500, not exactly 500. However, to strictly test the 'at least 500' boundary, we verify that 500 works. If the system has a hard limit of 500, the 501st would fail. Given 'at least 500', the system must handle 500. Let's assume standard behavior allows more, or we just verify the 500th is accessible. To be safe, let's just verify the 500th record is retrievable to prove storage integrity)."
        },
        {
          "no": 3,
          "action": "Retrieve and display the 500th casualty record.",
          "expected": "The 500th record is displayed correctly with all data intact."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Synchronization upon connectivity restoration",
      "covers": [
        "MED-005"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is offline. 10 local casualty records have been created and are marked for sync. Network connectivity is currently disabled.",
      "test_inputs": "10 local casualty records.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Enable network connectivity on the tablet.",
          "expected": "The application detects the connection and initiates synchronization."
        },
        {
          "no": 2,
          "action": "Wait for the synchronization process to complete.",
          "expected": "The local records are successfully uploaded to the server. The local status of these records changes to 'Synced' or similar."
        }
      ]
    },
    {
      "id": "TC-003",
      "title": "Conflict resolution keeping both versions",
      "covers": [
        "MED-005"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "A casualty record (ID: C-123) exists on the server. The application is offline. The local version of C-123 is modified (e.g., status changed to 'Stable'). Meanwhile, the server version of C-123 is modified via another client (e.g., status changed to 'Critical').",
      "test_inputs": "Local edit: Status='Stable'. Server edit: Status='Critical'.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Enable network connectivity to trigger synchronization.",
          "expected": "The application detects the conflict for record C-123."
        },
        {
          "no": 2,
          "action": "Check the local application view for record C-123.",
          "expected": "The application displays a conflict indication. Both versions (Local: 'Stable', Server: 'Critical') are preserved and available for manual review, rather than one overwriting the other automatically."
        }
      ]
    }
  ]
}

