{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gereksinim, belirli bir girdi (geçersiz belirteç) verildiğinde sistemin gözlemlenebilir davranışını (HTTP 401 yanıtı) tanımladığı için test ile doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Rol tabanlı erişim kontrolünün ve yetkisiz isteklerde HTTP 403 yanıtının, farklı rollerle yapılan istekler üzerinden sistemin çalıştırılarak gözlemlenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "Hız sınırlama eşiğinin aşılması durumunda HTTP 429 yanıtı ve Retry-After başlığının, kontrollü istek yükü uygulanarak sistemin davranışı gözlemlenerek doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Analiz"
      ],
      "rationale": "Belirli bir yük altında (2.000 istek/sn) 99. persentil gecikme metriklerinin karşılaştırılması, performans testlerinin sonuçlarının istatistiksel analizi gerektirdiği için analiz yöntemi uygundur."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "Arka uç gecikmesinin 5 saniyeyi aşması durumunda isteğin sonlandırılması ve HTTP 504 yanıtının, simüle edilmiş gecikme senaryolarıyla sistemin çalıştırılarak gözlemlenmesiyle doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "Yapılandırma değişikliğinin yeniden başlatma gerektirmeden ve aktif istekleri düşürmeden uygulanması, canlı sistem üzerinde değişiklik yapılarak ve istek akışı izlenerek test edilmelidir."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "İsteklerin loglanma davranışının ve log kayıtlarında beklenen alanların (izleme kimliği, süre vb.) bulunup bulunmadığının, istekler gönderildikten sonra log çıktısının incelenmesiyle doğrulanması gerekir."
